body.script:
(() => {
  'use strict';
  const tg = window.Telegram && window.Telegram.WebApp ? window.Telegram.WebApp : null;
  const $ = (id) => document.getElementById(id);
  const views = [...document.querySelectorAll('[data-view]')];
  const navButtons = [...document.querySelectorAll('[data-nav]')];
  const actionButtons = [...document.querySelectorAll('[data-action]')];
  const fallbackParams = {
    main:'main_menu', hub:'smart_hub', tasks:'tasks', wallet:'wallet', history:'history',
    campaigns:'campaigns', stats:'stats', marketplace:'marketplace', engagement:'engagement_mode',
    obligations:'engagement_obligations', rules:'community_rules', legal:'legal_docs', rewards:'rewards',
    referrals:'referrals', vip:'vip', admin:'admin', admin_queue:'admin_queue',
    admin_obligations:'admin_engagement_obligations', admin_logs:'admin_logs',
    owner_analytics:'owner_analytics', owner_release:'owner_release', owner_provider:'owner_provider'
  };
  let config = {brand_name:'Boostora', bot_url:''};
  let session = null;
  let toastTimer = null;

  function toast(text) {
    const node = $('toast');
    node.textContent = text;
    node.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => node.classList.remove('show'), 2600);
  }
  function setView(name) {
    views.forEach((view) => { view.hidden = view.dataset.view !== name; });
    navButtons.forEach((button) => button.classList.toggle('active', button.dataset.nav === name));
    window.scrollTo({top:0, behavior:'smooth'});
    try { tg && tg.HapticFeedback.selectionChanged(); } catch (_) {}
  }
  function setRoleVisibility(role) {
    document.querySelectorAll('.performer-only').forEach((node) => { node.hidden = role !== 'performer'; });
    document.querySelectorAll('.client-only').forEach((node) => { node.hidden = role !== 'client'; });
    $('workTitle').textContent = role === 'client' ? 'Продвижение' : role === 'performer' ? 'Задания' : 'Работа';
    $('workHint').textContent = role ? 'доступно по твоей роли' : 'сначала выбери роль в боте';
  }
  function openTelegram(url) {
    if (!url) { toast('Ссылка на бота пока не настроена.'); return; }
    try {
      if (tg && typeof tg.openTelegramLink === 'function') tg.openTelegramLink(url);
      else window.location.href = url;
    } catch (_) { window.location.href = url; }
  }
  function fallbackUrl(action) {
    if (!config.bot_url) return '';
    const param = fallbackParams[action];
    return param ? `${config.bot_url}?start=wa_${encodeURIComponent(param)}` : config.bot_url;
  }
  async function invokeAction(action, button) {
    if (button) button.disabled = true;
    try {
      if (!tg || !tg.initData) {
        openTelegram(fallbackUrl(action));
        return;
      }
      const response = await fetch('/api/miniapp/action', {
        method:'POST', headers:{'Content-Type':'application/json'},
        body:JSON.stringify({init_data:tg.initData, action})
      });
      const data = await response.json();
      if (response.status === 403) { toast('Этот раздел недоступен для твоей роли.'); return; }
      if (!response.ok || !data.open_url) throw new Error(data.error || 'action_failed');
      openTelegram(data.open_url);
    } catch (_) {
      toast('Не удалось открыть раздел. Попробуй ещё раз.');
    } finally {
      if (button) button.disabled = false;
    }
  }
  function renderDashboard(data) {
    const dashboard = data.dashboard || {};
    const role = (data.access && data.access.role) || dashboard.role || '';
    const roleText = role === 'client' ? 'Заказчик' : role === 'performer' ? 'Исполнитель' : 'Роль не выбрана';
    $('rolePill').textContent = data.access && data.access.is_owner ? 'Владелец' : data.access && data.access.is_admin ? 'Администратор' : roleText;
    setRoleVisibility(role);
    $('registrationNotice').hidden = !!dashboard.registered && !!role;

    const wallet = dashboard.wallet || {};
    const activity = dashboard.activity || {};
    const engagement = dashboard.engagement || {};
    $('balanceStat').textContent = wallet.available ?? 0;
    $('walletAvailable').textContent = wallet.available ?? 0;
    $('walletCampaign').textContent = wallet.campaign ?? 0;
    $('walletHold').textContent = wallet.hold ?? 0;
    $('walletEarned').textContent = wallet.earned ?? 0;
    if (role === 'client') {
      $('workStat').textContent = activity.client_active ?? 0;
      $('workLabel').textContent = 'активных кампаний';
    } else {
      $('workStat').textContent = `${activity.active_tasks ?? 0}/${activity.task_limit ?? 0}`;
      $('workLabel').textContent = 'активных заданий';
    }
    $('availableTasks').textContent = activity.available_tasks ?? 0;
    $('campaignCount').textContent = activity.client_campaigns ?? 0;
    $('activeCampaignCount').textContent = activity.client_active ?? 0;
    const mode = engagement.mode === 'pro' ? 'PRO' : engagement.mode === 'standard' ? 'Standard' : '—';
    $('modeStat').textContent = mode;
    $('modeCaption').textContent = mode === '—' ? 'режим не выбран' : `текущий режим: ${mode}`;
    $('obligationStat').textContent = engagement.remaining ?? 0;
    const required = Math.max(Number(engagement.required || 0), 1);
    const done = Number(engagement.done || 0);
    const percent = Math.max(0, Math.min(100, Math.round(done * 100 / required)));
    $('obligationProgress').style.width = `${percent}%`;
    $('obligationText').textContent = Number(engagement.remaining || 0) > 0
      ? `Выполнено ${done}, осталось ${engagement.remaining}.`
      : 'Активных обязательств нет.';

    const isAdmin = !!(data.access && data.access.is_admin);
    const isOwner = !!(data.access && data.access.is_owner);
    $('adminPanel').hidden = !isAdmin;
    $('ownerPanel').hidden = !isOwner;
    if (isOwner && data.owner_meta) $('ownerVersion').textContent = data.owner_meta.version || '';

    const allowed = new Set((data.access && data.access.allowed_actions) || []);
    actionButtons.forEach((button) => {
      const action = button.dataset.action;
      if ((action.startsWith('admin') || action.startsWith('owner')) && !allowed.has(action)) button.hidden = true;
    });
  }
  async function loadConfig() {
    const response = await fetch('/api/config', {cache:'no-store'});
    const data = await response.json();
    if (!response.ok || !data.ok) throw new Error('config');
    config = data;
    $('brandName').textContent = data.brand_name || 'Boostora';
  }
  async function authenticate() {
    if (!tg || !tg.initData) {
      $('connectionBadge').textContent = 'веб-предпросмотр';
      $('telegramState').textContent = 'Открой Mini App из Telegram, чтобы увидеть личный кабинет.';
      $('userDetails').textContent = 'В браузере доступен только предварительный просмотр.';
      setRoleVisibility('');
      return;
    }
    const response = await fetch('/api/telegram/session', {
      method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({init_data:tg.initData})
    });
    const data = await response.json();
    if (!response.ok || !data.authenticated) throw new Error(data.reason || 'auth');
    session = data;
    const user = data.user || {};
    const name = [user.first_name,user.last_name].filter(Boolean).join(' ') || 'Пользователь Telegram';
    $('userName').textContent = name;
    $('userDetails').textContent = user.username ? `@${user.username} · профиль подтверждён` : 'Профиль подтверждён Telegram';
    $('connectionBadge').textContent = 'подключено';
    $('telegramState').textContent = `Здравствуйте, ${user.first_name || name}. Все кнопки готовы.`;
    renderDashboard(data);
    try {
      fetch('/api/miniapp/open', {method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({init_data:tg.initData,source:'interactive_miniapp',platform:tg.platform || ''})});
    } catch (_) {}
  }

  navButtons.forEach((button) => button.addEventListener('click', () => setView(button.dataset.nav)));
  actionButtons.forEach((button) => button.addEventListener('click', () => invokeAction(button.dataset.action, button)));
  if (tg) {
    tg.ready(); tg.expand();
    try { tg.enableClosingConfirmation(); } catch (_) {}
  }
  loadConfig().catch(() => toast('Не удалось загрузить настройки.')).finally(() => {
    authenticate().catch(() => {
      $('connectionBadge').textContent = 'ошибка подключения';
      $('telegramState').textContent = 'Закрой Mini App и открой её снова кнопкой из Boostora.';
      toast('Сессия Telegram не подтверждена.');
    });
  });
})();
